package com.multitenanterp.payroll;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payroll/inputs") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER','PAYROLL_EXECUTIVE')")
public class PayrollInputController{private final PayrollInputService service;public PayrollInputController(PayrollInputService service){this.service=service;}@GetMapping("/statutory-rules") public List<StatutoryRule> rules(){return service.rules();}@PostMapping("/statutory-rules") @ResponseStatus(HttpStatus.CREATED) public StatutoryRule rule(@Valid @RequestBody SaveStatutoryRuleRequest r){return service.saveRule(null,r);}@PutMapping("/statutory-rules/{id}") public StatutoryRule rule(@PathVariable UUID id,@Valid @RequestBody SaveStatutoryRuleRequest r){return service.saveRule(id,r);}@GetMapping("/variables") public List<PayrollVariableInput> variables(@RequestParam int year,@RequestParam int month){return service.variables(year,month);}@PostMapping("/variables") @ResponseStatus(HttpStatus.CREATED) public PayrollVariableInput variable(@Valid @RequestBody SavePayrollVariableInputRequest r,Authentication a){return service.saveVariable(null,r,a.getName());}@PutMapping("/variables/{id}") public PayrollVariableInput variable(@PathVariable UUID id,@Valid @RequestBody SavePayrollVariableInputRequest r,Authentication a){return service.saveVariable(id,r,a.getName());}}
